// Populate region field on all entries in COUNTRY_DATA
for (const entry of Object.values(COUNTRY_DATA)) {
  if (entry && !entry.region) {
    let reg = REGION_MAP_BY_ISO3[entry.iso3];
    if (!reg) {
      if (entry.name === "N. Cyprus") reg = "Southern Europe";
      else if (entry.name === "Somaliland") reg = "East Africa";
      else if (entry.name === "Kosovo" || entry.id === "XKX") reg = "Southern Europe";
      else reg = "Global";
    }
    entry.region = reg;
  }
}

/**
 * Dynamically retrieves comprehensive country details for a given GeoJSON feature or identifier.
 * Uses ISO codes (ISO 3166-1 alpha-2, alpha-3, numeric) or display names.
 * @param {Object|string} featureOrId - GeoJSON feature or identifier string
 * @returns {Object|null} Country details object
 */
export function getCountryDetails(featureOrId) {
  if (!featureOrId) return null;

  let key = null;

  if (typeof featureOrId === 'string') {
    key = featureOrId;
  } else if (typeof featureOrId === 'object') {
    if (featureOrId.id !== undefined && featureOrId.id !== null) {
      const paddedId = String(featureOrId.id).padStart(3, '0');
      if (COUNTRY_DATA[paddedId]) return COUNTRY_DATA[paddedId];
    }
    if (featureOrId.properties && featureOrId.properties.name) {
      key = featureOrId.properties.name;
    }
  }

  if (key && COUNTRY_DATA[key]) {
    return COUNTRY_DATA[key];
  }

  if (key) {
    const lowerKey = key.toLowerCase();
    for (const recordKey of Object.keys(COUNTRY_DATA)) {
      if (recordKey.toLowerCase() === lowerKey) {
        return COUNTRY_DATA[recordKey];
      }
    }
  }

  return {
    name: (typeof featureOrId === 'object' && featureOrId.properties && featureOrId.properties.name) ? featureOrId.properties.name : 'Selected Territory',
    capital: 'Capital City',
    capitalLat: 0,
    capitalLon: 0,
    continent: 'Global',
    region: 'Global',
    population: 'Information unavailable',
    area: 'Information unavailable',
    currency: 'Information unavailable',
    language: 'Information unavailable',
    flagCode: null,
    flagEmoji: '🌐',
    flagUrl: null,
  };
}
